nation":"Câu nghe được là: I am at home."},{"id":"a0-2-g1","skill":"grammar","prompt":"You ___ my friend.","options":["is","are","am"],"answer":"are","explanation":"“You” đi với “are”, kể cả khi chỉ nói với một người."},{"id":"a0-2-g2","skill":"grammar","prompt":"___ are happy.","options":["I","You","He"],"answer":"You","explanation":"Trong ba chủ ngữ này, chỉ “You” đi với “are”."},{"id":"a0-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"You are my friend.","audio":"/audio/lesson-a0-2.mp3","explanation":"Câu mẫu là: You are my friend."},{"id":"a0-2-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["You is my friend.","You are my friend.","You am my friend."],"answer":"You are my friend.","explanation":"“You” đi với “are”, kể cả khi chỉ nói với một người."},{"id":"a0-2-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["I are happy.","You are happy.","He are happy."],"answer":"You are happy.","explanation":"Trong ba chủ ngữ này, chỉ “You” đi với “are”."},{"id":"a0-2-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"You are very kind.","audio":"/audio/listen-a0-2-2.mp3","explanation":"Câu nghe được là: You are very kind."},{"id":"a0-2-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"You are a student.","audio":"/audio/listen-a0-2-3.mp3","explanation":"Câu nghe được là: You are a student."},{"id":"reader-a0-2-r0","skill":"reading","prompt":"Who is Tom?","options":["A student","A teacher","A driver"],"answer":"A student","explanation":"Đáp án “A student” phù hợp với thông tin trong bài. Đọc lại đoạn “A new friend” để đối chiếu."},{"id":"reader-a0-2-r1","skill":"reading","prompt":"What colour is Tom’s pen?","options":["Blue","Red","Black"],"answer":"Blue","explanation":"Đáp án “Blue” phù hợp với thông tin trong bài. Đọc lại đoạn “A new friend” để đối chiếu."},{"id":"reader-a0-2-r2","skill":"reading","prompt":"What do they do after class?","options":["Walk to the bus","Go swimming","Buy a book"],"answer":"Walk to the bus","explanation":"Đáp án “Walk to the bus” phù hợp với thông tin trong bài. Đọc lại đoạn “A new friend” để đối chiếu."},{"id":"a0-3-g1","skill":"grammar","prompt":"She ___ a teacher.","options":["are","am","is"],"answer":"is","explanation":"“She” là ngôi thứ ba số ít nên dùng “is”."},{"id":"a0-3-g2","skill":"grammar","prompt":"It ___ a book.","options":["am","is","are"],"answer":"is","explanation":"“It” chỉ một vật và đi với “is”."},{"id":"a0-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She is a teacher.","audio":"/audio/lesson-a0-3.mp3","explanation":"Câu mẫu là: She is a teacher."},{"id":"a0-3-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["She are a teacher.","She am a teacher.","She is a teacher."],"answer":"She is a teacher.","explanation":"“She” là ngôi thứ ba số ít nên dùng “is”."},{"id":"a0-3-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It am a book.","It is a book.","It are a book."],"answer":"It is a book.","explanation":"“It” chỉ một vật và đi với “is”."},{"id":"a0-3-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"He is my friend.","audio":"/audio/listen-a0-3-2.mp3","explanation":"Câu nghe được là: He is my friend."},{"id":"a0-3-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"It is a pen.","audio":"/audio/listen-a0-3-3.mp3","explanation":"Câu nghe được là: It is a pen."},{"id":"reader-a0-3-r0","skill":"reading","prompt":"What is the mother?","options":["A teacher","A cook","A student"],"answer":"A teacher","explanation":"Đáp án “A teacher” phù hợp với thông tin trong bài. Đọc lại đoạn “The people in my home” để đối chiếu."},{"id":"reader-a0-3-r1","skill":"reading","prompt":"Where is the father?","options":["In the kitchen","On a bus","At school"],"answer":"In the kitchen","explanation":"Đáp án “In the kitchen” phù hợp với thông tin trong bài. Đọc lại đoạn “The people in my home” để đối chiếu."},{"id":"reader-a0-3-r2","skill":"reading","prompt":"What colour is the cat?","options":["White","Black","Brown"],"answer":"White","explanation":"Đáp án “White” phù hợp với thông tin trong bài. Đọc lại đoạn “The people in my home” để đối chiếu."},{"id":"a0-4-g1","skill":"grammar","prompt":"This is ___ book.","options":["a","an","two"],"answer":"a","explanation":"“Book” bắt đầu bằng âm /b/, nên dùng “a”."},{"id":"a0-4-g2","skill":"grammar","prompt":"It is ___ cat.","options":["an","a","three"],"answer":"a","explanation":"“Cat” bắt đầu bằng âm /k/, nên dùng “a”."},{"id":"a0-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"This is a book.","audio":"/audio/lesson-a0-4.mp3","explanation":"Câu mẫu là: This is a book."},{"id":"a0-4-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["This is a book.","This is an book.","This is two book."],"answer":"This is a book.","explanation":"“Book” bắt đầu bằng âm /b/, nên dùng “a”."},{"id":"a0-4-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It is an cat.","It is a cat.","It is three cat."],"answer":"It is a cat.","explanation":"“Cat” bắt đầu bằng âm /k/, nên dùng “a”."},{"id":"a0-4-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have a cat.","audio":"/audio/listen-a0-4-2.mp3","explanation":"Câu nghe được là: I have a cat."},{"id":"a0-4-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"This is a cup.","audio":"/audio/listen-a0-4-3.mp3","explanation":"Câu nghe được là: This is a cup."},{"id":"reader-a0-4-r0","skill":"reading","prompt":"Where is the pen?","options":["In the bag","In the cup","Under the chair"],"answer":"In the bag","explanation":"Đáp án “In the bag” phù hợp với thông tin trong bài. Đọc lại đoạn “A bag for school” để đối chiếu."},{"id":"reader-a0-4-r1","skill":"reading","prompt":"What colour is the friend’s bag?","options":["Red","Blue","Green"],"answer":"Red","explanation":"Đáp án “Red” phù hợp với thông tin trong bài. Đọc lại đoạn “A bag for school” để đối chiếu."},{"id":"reader-a0-4-r2","skill":"reading","prompt":"What are they ready for?","options":["Class","Dinner","A holiday"],"answer":"Class","explanation":"Đáp án “Class” phù hợp với thông tin trong bài. Đọc lại đoạn “A bag for school” để đối chiếu."},{"id":"a0-5-g1","skill":"grammar","prompt":"It is ___ apple.","options":["a","an","two"],"answer":"an","explanation":"“Apple” bắt đầu bằng âm /æ/, nên dùng “an”."},{"id":"a0-5-g2","skill":"grammar","prompt":"This is ___ orange.","options":["a","an","three"],"answer":"an","explanation":"“Orange” bắt đầu bằng âm nguyên âm, nên dùng “an”."},{"id":"a0-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"It is an apple.","audio":"/audio/lesson-a0-5.mp3","explanation":"Câu mẫu là: It is an apple."},{"id":"a0-5-g3","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["It is a apple.","It is an apple.","It is two apple."],"answer":"It is an apple.","explanation":"“Apple” bắt đầu bằng âm /æ/, nên dùng “an”."},{"id":"a0-5-g4","skill":"grammar","kind":"repair","prompt":"Chọn cách viết đúng theo quy tắc của bài.","options":["This is a orange.","This is an orange.","This is three orange."],"answer":"This is an orange.","explanation":"“Orange” bắt đầu bằng âm nguyên âm, nên dùng “an”."},{"id":"a0-5-d2","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"This is an orange.","audio":"/audio/listen-a0-5-2.mp3","explanation":"Câu nghe được là: This is an orange."},{"id":"a0-5-d3","skill":"listening","kind":"dictation","prompt":"Nghe và viết lại câu.","answer":"I have an apple.","audio":"/audio/listen-a0-5-3.mp3","explana